INSERT INTO use_cases (id,title,category,status,business_problem,solution_description,ai_capability,business_area,value_stream,executive_sponsor,funding_status,risks,requestor_name,planview_tracking_number,annual_value_low_m,annual_value_high_m,complexity,time_to_value_low_mo,time_to_value_high_mo,data_sources,prerequisites) VALUES ('6dc2b6d2-6b0d-4f4a-8aed-ad1cf33db1e1','Outage Detection & Prediction','Distribution','Under Review','Slow detection of outages drives long SAIDI minutes, wasted truck rolls, and customer dissatisfaction. AMI last-gasp signals are not integrated with OMS today.','Integrate AMI last-gasp / power-on events with OMS and SCADA to detect, predict, and pre-stage for outages. Foundational to FLISR and storm response.','Anomaly Detection','Distribution Operations','Distribution',NULL,NULL,NULL,NULL,NULL,30,62,3,9,15,'AMI (last-gasp/power-on), OMS, SCADA, weather, historical outage records','AMI + OMS integration; clean GIS network model');
INSERT INTO use_cases (id,title,category,status,business_problem,solution_description,ai_capability,business_area,value_stream,executive_sponsor,funding_status,risks,requestor_name,planview_tracking_number,annual_value_low_m,annual_value_high_m,complexity,time_to_value_low_mo,time_to_value_high_mo,data_sources,prerequisites) VALUES ('bd01924c-ccca-46a3-bdb4-7ef472760ac5','Fault Location, Isolation, and Service Restoration (FLISR)','Distribution','Under Review','Manual fault location and restoration takes 8+ SAIDI minutes per event and consumes 500,000 crew hours annually.','Use AMI, OMS, GIS, and recloser/switch telemetry to automatically locate, isolate, and restore faults. Direct extension of outage detection.','Optimization','Distribution Operations','Distribution',NULL,NULL,NULL,NULL,NULL,25,52,3,12,18,'AMI, OMS, GIS network model, SCADA (reclosers/switches), fault indicators','Outage Detection & Prediction; clean GIS connectivity model');
INSERT INTO use_cases (id,title,category,status,business_problem,solution_description,ai_capability,business_area,value_stream,executive_sponsor,funding_status,risks,requestor_name,planview_tracking_number,annual_value_low_m,annual_value_high_m,complexity,time_to_value_low_mo,time_to_value_high_mo,data_sources,prerequisites) VALUES ('0ddfc920-4926-4098-8bc6-6eb84508f8cc','Predictive Maintenance for OH & UG Assets','Distribution','Refinement','200,000 distribution transformers with a 5% annual failure rate drive emergency O&M premiums and customer interruptions.','Combine inspection records, AMI power-quality data, transformer loading, GIS, weather, and failure history to predict failures and shift from reactive to planned maintenance.','Predictive Maintenance','Asset Management','Distribution',NULL,NULL,NULL,NULL,NULL,22,45,3,15,24,'Inspection records, AMI power quality, transformer loading, GIS, weather, failure history','AMI integration; historical inspection / failure records digitized');
INSERT INTO use_cases (id,title,category,status,business_problem,solution_description,ai_capability,business_area,value_stream,executive_sponsor,funding_status,risks,requestor_name,planview_tracking_number,annual_value_low_m,annual_value_high_m,complexity,time_to_value_low_mo,time_to_value_high_mo,data_sources,prerequisites) VALUES ('ede2766c-c824-45e4-86a8-d57b41b4df1e','Load Forecasting at Feeder Level','Distribution','Refinement','System-level load forecasts miss feeder-level variation, leading to over-built capital and stalled DER interconnection studies.','Granular AMI-driven load forecasts per feeder, enabling capacity planning, DER readiness, and EV-charging planning. Critical input to hosting capacity analysis.','Forecasting','Distribution Planning','Distribution',NULL,NULL,NULL,NULL,NULL,12,25,3,12,18,'AMI interval data, weather, DER interconnection records, GIS feeder maps, EV charging data','AMI interval data aggregated by feeder and transformer');
INSERT INTO use_cases (id,title,category,status,business_problem,solution_description,ai_capability,business_area,value_stream,executive_sponsor,funding_status,risks,requestor_name,planview_tracking_number,annual_value_low_m,annual_value_high_m,complexity,time_to_value_low_mo,time_to_value_high_mo,data_sources,prerequisites) VALUES ('2da27bc8-5f3e-44ca-a6f9-37c009e97798','Grid Reliability Monitoring','Distribution','Approved','Reliability reporting is manual; 15 analysts spend 50% of their time on SAIDI/SAIFI/CAIDI compilation rather than analysis.','Reporting and dashboard layer on top of AMI/SCADA/OMS data. Low incremental complexity once Phase 1 data is in place. Drives regulatory reporting automation and targeted investment.','Other','Regulatory & Reliability','Distribution',NULL,NULL,NULL,NULL,NULL,8,18,2,6,9,'AMI, SCADA, OMS, power quality meters, GIS, reliability indices','Phase 1 AMI/OMS/SCADA integration');
INSERT INTO use_cases (id,title,category,status,business_problem,solution_description,ai_capability,business_area,value_stream,executive_sponsor,funding_status,risks,requestor_name,planview_tracking_number,annual_value_low_m,annual_value_high_m,complexity,time_to_value_low_mo,time_to_value_high_mo,data_sources,prerequisites) VALUES ('64129296-683a-4dc7-a1bb-011d059e14ed','DER & EV Charging Management','Distribution','Backlog','Uncoordinated DER and EV charging is overloading distribution transformers and forcing expensive capacity upgrades.','Manage bidirectional power flows and EV-charging impacts using AMI, DER telemetry, and feeder models. Enables FERC Order 2222 market participation.','Optimization','Distribution Operations','Distribution',NULL,NULL,NULL,NULL,NULL,30,65,4,18,24,'AMI, DER telemetry, EV charger data, feeder models, weather, interconnection records','Load Forecasting at Feeder Level; DER telemetry feeds');
INSERT INTO use_cases (id,title,category,status,business_problem,solution_description,ai_capability,business_area,value_stream,executive_sponsor,funding_status,risks,requestor_name,planview_tracking_number,annual_value_low_m,annual_value_high_m,complexity,time_to_value_low_mo,time_to_value_high_mo,data_sources,prerequisites) VALUES ('553769f6-230f-459a-80f5-8e2164329a81','Grid Model Clean-up & Connectivity Inference','Distribution','Refinement','15-25% GIS connectivity error rate causes failed work orders, inaccurate outage locations, and FLISR misfires.','Use ML to infer and correct connectivity errors in GIS / network models by reconciling GIS with AMI, SCADA, and as-built records.','Anomaly Detection','GIS & Asset Records','Distribution',NULL,NULL,NULL,NULL,NULL,8,18,3,12,18,'GIS, AMI, SCADA, as-built records, work orders, connectivity models','Phase 1 data quality issues triaged');
INSERT INTO use_cases (id,title,category,status,business_problem,solution_description,ai_capability,business_area,value_stream,executive_sponsor,funding_status,risks,requestor_name,planview_tracking_number,annual_value_low_m,annual_value_high_m,complexity,time_to_value_low_mo,time_to_value_high_mo,data_sources,prerequisites) VALUES ('43c9ed10-2c51-4fbf-8194-e211e20ae643','Storm Impact Prediction & Crew Pre-Staging','Distribution','Backlog','Major storms cost $100M/yr in restoration; crews are staged reactively rather than predictively.','Predict storm damage by asset vulnerability and weather forecast, pre-stage crews and materials, coordinate mutual aid more efficiently.','Forecasting','Emergency Response','Distribution',NULL,NULL,NULL,NULL,NULL,22,48,3,12,18,'Weather forecasts, historical storm damage, asset vulnerability, GIS, crew/equipment locations','Outage Detection & Prediction; Grid Reliability Monitoring');
INSERT INTO use_cases (id,title,category,status,business_problem,solution_description,ai_capability,business_area,value_stream,executive_sponsor,funding_status,risks,requestor_name,planview_tracking_number,annual_value_low_m,annual_value_high_m,complexity,time_to_value_low_mo,time_to_value_high_mo,data_sources,prerequisites) VALUES ('45de8f56-2015-49da-8c29-920a33197dbe','Voltage Optimization & Loss Reduction','Distribution','Backlog','Technical losses run ~5% of 5,000 MW system load; voltage violations and reactive-power costs are addressable but unmanaged.','Optimize volt/VAR settings across the distribution network using AMI voltage data and capacitor/regulator telemetry. Enables conservation voltage reduction (CVR).','Optimization','Distribution Operations','Distribution',NULL,NULL,NULL,NULL,NULL,18,38,3,12,18,'AMI voltage data, SCADA, capacitor bank status, regulator settings, feeder models','Clean AMI voltage data; volt/VAR device telemetry');
INSERT INTO use_cases (id,title,category,status,business_problem,solution_description,ai_capability,business_area,value_stream,executive_sponsor,funding_status,risks,requestor_name,planview_tracking_number,annual_value_low_m,annual_value_high_m,complexity,time_to_value_low_mo,time_to_value_high_mo,data_sources,prerequisites) VALUES ('639b882e-1a73-454d-bb0a-edfeb902d8eb','Hosting Capacity Analysis','Distribution','Backlog','DER interconnection cycle time is 3-6 months; engineering studies are a bottleneck.','Quantify where the grid can accept new DERs without upgrades. Feeder-by-feeder hosting capacity maps cut interconnection studies to 2-4 weeks.','Optimization','DER Interconnection','Distribution',NULL,NULL,NULL,NULL,NULL,15,32,4,12,18,'Feeder models, AMI, DER interconnection data, load forecasts, protection settings, thermal limits','Load Forecasting at Feeder Level');
INSERT INTO use_cases (id,title,category,status,business_problem,solution_description,ai_capability,business_area,value_stream,executive_sponsor,funding_status,risks,requestor_name,planview_tracking_number,annual_value_low_m,annual_value_high_m,complexity,time_to_value_low_mo,time_to_value_high_mo,data_sources,prerequisites) VALUES ('43837251-d397-4c24-ab77-155b9bc8377d','Distribution Network Digital Twin','Distribution','Backlog','No simulation environment to test switching, DER scenarios, or planning decisions before they hit the live grid.','Full distribution digital twin combining AMI, SCADA, GIS, DER telemetry, weather, and real-time switching state. Enables operational simulation, planning, and real-time optimization.','Optimization','Distribution Engineering','Distribution',NULL,NULL,NULL,NULL,NULL,35,72,5,48,60,'AMI, SCADA, GIS, DER telemetry, weather, real-time switching state, customer data','All Phase 1-2 distribution data; clean GIS model');
INSERT INTO use_cases (id,title,category,status,business_problem,solution_description,ai_capability,business_area,value_stream,executive_sponsor,funding_status,risks,requestor_name,planview_tracking_number,annual_value_low_m,annual_value_high_m,complexity,time_to_value_low_mo,time_to_value_high_mo,data_sources,prerequisites) VALUES ('28bc7177-1de0-4087-b85a-7e2153dffb3d','Automated Work Package Generation for Crews','Distribution','Backlog','200 planners spend 50% of their time manually assembling work packages; 5,000 jobs/yr are delayed by gaps.','AI assembles complete work packages (instructions, materials, permits, safety plans) from work orders, GIS, asset condition, crew skills, and material availability.','Generative AI / Agents','Work Management','Distribution',NULL,NULL,NULL,NULL,NULL,18,38,4,36,48,'Work orders, GIS, asset condition, crew skills/certifications, material availability, schedules','Mature work-management data; integrated material/skills systems');
INSERT INTO use_cases (id,title,category,status,business_problem,solution_description,ai_capability,business_area,value_stream,executive_sponsor,funding_status,risks,requestor_name,planview_tracking_number,annual_value_low_m,annual_value_high_m,complexity,time_to_value_low_mo,time_to_value_high_mo,data_sources,prerequisites) VALUES ('586b594e-1950-4785-8f91-2746ee5b2fd3','Automated Work Order Creation & Crew Dispatching','Distribution','Backlog','50 dispatchers spend 37% of their time on manual work order creation; crew utilization and overtime remain stubbornly suboptimal.','Close the loop from fault detection through automated dispatch using OMS, the digital twin, crew locations, and priority models.','Generative AI / Agents','Dispatch Operations','Distribution',NULL,NULL,NULL,NULL,NULL,25,52,5,48,60,'OMS, digital twin, crew locations, skills, equipment, traffic, priority models','Distribution Network Digital Twin');
INSERT INTO use_cases (id,title,category,status,business_problem,solution_description,ai_capability,business_area,value_stream,executive_sponsor,funding_status,risks,requestor_name,planview_tracking_number,annual_value_low_m,annual_value_high_m,complexity,time_to_value_low_mo,time_to_value_high_mo,data_sources,prerequisites) VALUES ('0bf4caf6-3a1b-4db9-b2f5-78022b27bdc6','Self-healing Distribution Networks','Distribution','Backlog','Sustained outages still drive SAIDI minutes that customers and regulators no longer accept.','Ultimate distribution automation: the network detects, isolates, and restores faults autonomously by orchestrating FLISR, DERs, switching, and protection.','Optimization','Distribution Operations','Distribution',NULL,NULL,NULL,NULL,NULL,45,92,5,60,72,'Digital twin, FLISR automation, DER orchestration, real-time switching, protection coordination','Distribution Network Digital Twin; Automated Work Order Creation; FLISR');
INSERT INTO use_cases (id,title,category,status,business_problem,solution_description,ai_capability,business_area,value_stream,executive_sponsor,funding_status,risks,requestor_name,planview_tracking_number,annual_value_low_m,annual_value_high_m,complexity,time_to_value_low_mo,time_to_value_high_mo,data_sources,prerequisites) VALUES ('d507ce52-9375-44ee-90d9-3cbd86096e84','Hyper-local Probabilistic Risk Pricing','Distribution','Backlog','$300M annual distribution capital is allocated with limited asset-level risk insight; 5 high-consequence failures per year are currently preventable.','Price risk at the individual asset/segment level using probabilistic failure and consequence models. Enables surgical investment decisions and insurance optimization.','Predictive Maintenance','Asset Management','Distribution',NULL,NULL,NULL,NULL,NULL,20,42,4,48,60,'Asset condition, weather exposure, vegetation, customer density, failure probability, consequence models','Predictive Maintenance baseline; asset condition data integrated');
